import SnackBar from "@/components/SnackBar.vue";
import AddPrefix from "./AddPrefix.vue";
import { customer_function } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import DeleteCustomer from "./DeleteCustomer.vue";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
export default {
  components: {
    SnackBar,
    AddPrefix,
    DeleteCustomer
  },
  props: {
    searchValue: {
      type: String,
      default: ""
    }
  },
  data() {
    return {
      SnackBarComponent: {},
      tableLoading: false,
      componentCheck: 0,
      suppliereHeaders: [{
        title: "Reference ID",
        value: "customer_display_id",
        sortable: false
      }, {
        title: "Legal Name",
        value: "legal_name",
        sortable: false
      }, {
        title: "Business Type",
        value: "customer_type",
        sortable: false
      }, {
        title: "Product Name",
        value: "item_details_names",
        sortable: false
      }, {
        title: "Contact Name",
        value: "primary_contact_name",
        sortable: false
      }, {
        title: "Email ID",
        value: "customer_email_id",
        sortable: false
      }, {
        title: "Contact No",
        value: "primary_contact_no",
        sortable: false
      }, {
        title: "Address",
        value: "address_line_1",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }],
      customerRecords: [],
      fixed: false,
      customerItem: {},
      addPrefixDialog: false,
      deleteCustomerDialog: false,
      rowInfo: {},
      prefix: "",
      prefixData: "",
      // Pagination properties
      itemsPerPage: 10,
      currentPage: 1,
      sortBy: [{
        key: "customer_display_id",
        order: "asc"
      }],
      windowHeight: 0,
      tableHeight: 0
    };
  },
  computed: {
    filteredSuppliers() {
      if (!this.searchValue) return this.customerRecords;
      const search = this.searchValue.toLowerCase();
      return this.customerRecords.filter(item => {
        return Object.values(item).filter(v => v !== null && v !== undefined).join(" ").toLowerCase().includes(search);
      });
    },
    totalItems() {
      return this.filteredSuppliers.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    paginatedItems() {
      const sortedItems = this.filteredSuppliers.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (Array.isArray(aValue) && Array.isArray(bValue)) {
            for (let i = 0; i < aValue.length; i++) {
              if (aValue[i] < bValue[i]) return sort.order === "asc" ? -1 : 1;
              if (aValue[i] > bValue[i]) return sort.order === "asc" ? 1 : -1;
            }
            continue;
          }
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async created() {
    this.windowHeight = window.innerHeight - 120;
    this.tableHeight = this.windowHeight - 120;
    await this.fetch_customers();
  },
  watch: {
    searchValue() {
      this.currentPage = 1;
    },
    currentPage() {
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    getContactParts(contact) {
      if (!contact) return {
        code: "",
        number: ""
      };
      const separator = contact.includes("_") ? "_" : contact.includes("-") ? "-" : null;
      if (!separator) return {
        code: "",
        number: contact
      };
      const [code, number] = contact.split(separator);
      return {
        code,
        number
      };
    },
    Add_customer() {
      this.$router.push("/home/CreateCustomer");
    },
    Add_prefix() {
      this.componentCheck = 1;
      this.addPrefixDialog = true;
      this.prefixData = this.prefix;
    },
    Edit_Customer(item) {
      this.$router.push("/home/EditCustomer");
      this.$store.commit("SetcustomerData", item);
      // console.log("item", item)
    },
    View_Customer(item) {
      this.$router.push("/home/ViewCustomer");
      this.$store.commit("SetcustomerData", item);
      // console.log("item", item)
    },
    Delete_customer(item) {
      this.componentCheck = 2;
      this.deleteCustomerDialog = true;
      this.rowInfo = item;
    },
    download_item() {
      const headers = ["Legal Name of Business*", "Brand Name", "Address 1 *", "Address 2", "GST Id", "PAN Id", "CIN Number", "Primary Name*", "Primary Email ID*", "Primary Country Code*", "Primary Contact Number*", "Primary Designation*"];
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
      let fileName = firstName ? ` ${firstName}_Members Template.xlsx` : "Members Template.xlsx";
      const ws = XLSX.utils.aoa_to_sheet([headers]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
      XLSX.writeFile(wb, fileName);
    },
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addPrefixDialog = false;
      this.deleteCustomerDialog = false;
      this.fetch_customers();
    },
    async fetch_S3_file(value) {
      let responseData = null;
      let data = null;
      try {
        const response = await fetch(value);
        if (!response.ok) {
          throw new Error(`Failed to fetch the file: ${response.statusText} (Status Code: ${response.status})`);
        }
        if (!response.headers.get("Content-Type").includes("application/json")) {
          throw new Error("The file is not in JSON format");
        }
        responseData = await response.text();
        try {
          data = JSON.parse(responseData);
        } catch (jsonError) {
          throw new Error("Error parsing JSON response: " + jsonError.message);
        }
        return data;
      } catch (error) {
        console.error("Error fetching file:", error);
        this.errorMessage = "Error fetching file: " + error.message;
      } finally {}
    },
    async fetch_customers() {
      this.customerRecords = [];
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(customer_function, {
          input: {
            action_type: "LIST_CUSTOMER"
          }
        }));
        var response = JSON.parse(result.data.customer_function);
        if (response.Status == "SUCCESS") {
          const details = this.$store.getters.GetOrgDetails;
          // console.log(details.s3_details,'details.s3_details');
          const signedUrl = await getS3SignedUrl(response.url, details.s3_details);
          // console.log(signedUrl,'signedUrl');
          if (signedUrl) {
            let updatedCustomer = await this.fetch_S3_file(signedUrl);
            this.customerRecords = updatedCustomer;
          }
          // console.log(" this.customerRecords",  this.customerRecords);
          const prefixValue = response.customer_display_id;
          this.prefix = prefixValue;
          this.tableLoading = false;
        } else {
          this.customerRecords = [];
          const prefixValue = response.customer_display_id;
          this.prefix = prefixValue;
          this.tableLoading = false;
        }
      } catch (error) {
        this.customerRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "customer_display_id") {
        const str = String(value);
        const prefix = str.match(/^[A-Za-z]+/)?.[0] || "";
        const number = parseInt(str.match(/\d+/)?.[0] || "0", 10);
        return [prefix.toLowerCase(), number];
      }
      if (key === "legal_name" || key === "primary_contact_name" || key === "customer_type") {
        return value.toLowerCase();
      }
      return value;
    }
  }
};
